use rustmotion::Video;

fn main() {
    let video = Video::new(1920, 1080)
        .fps(30)
        .background("#0a0a1a");

    video.add_scene(|scene| {
        scene.text("Hello, world!")
            .font_size(64)
            .preset("fade_in_up");
    });

    video.render("output.mp4").unwrap();
}
